-- =================================================================================================
-- Students: automatic admission numbers (ADR-0020). Generated by Prisma, plus row security.
-- =================================================================================================


-- AlterTable
ALTER TABLE "institutions" ADD COLUMN     "admission_no_pattern" TEXT;

-- CreateTable
CREATE TABLE "admission_sequences" (
    "organization_id" UUID NOT NULL,
    "institution_id" UUID NOT NULL,
    "period" TEXT NOT NULL,
    "next_value" INTEGER NOT NULL DEFAULT 1,

    CONSTRAINT "admission_sequences_pkey" PRIMARY KEY ("institution_id","period")
);

-- CreateIndex
CREATE INDEX "admission_sequences_organization_id_idx" ON "admission_sequences"("organization_id");

-- AddForeignKey
ALTER TABLE "admission_sequences" ADD CONSTRAINT "admission_sequences_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "admission_sequences" ADD CONSTRAINT "admission_sequences_institution_id_fkey" FOREIGN KEY ("institution_id") REFERENCES "institutions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- (by hand) Row security: the same rule as every organization table
ALTER TABLE "admission_sequences" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "admission_sequences" FORCE ROW LEVEL SECURITY;
CREATE POLICY organization_isolation ON "admission_sequences"
  USING (current_setting('app.bypass_rls', true) = 'on'
         OR "organization_id"::text = current_setting('app.organization_id', true))
  WITH CHECK (current_setting('app.bypass_rls', true) = 'on'
         OR "organization_id"::text = current_setting('app.organization_id', true));
